/* Priority source readers preserve published requirements; recommendations never become approved audits. */
let bellevueCatalogPromise;
function getBellevueCatalog(){return bellevueCatalogPromise||=(fetch('bellevue-curricula.json').then(r=>{if(!r.ok)throw Error('Bellevue source snapshot unavailable.');return r.json()}).catch(e=>{bellevueCatalogPromise=null;throw e}))}
function bellevueCatalogPage(){return journeyPage(2,'Bellevue. Your next step, mapped.',`<p class="journey-lede">Search 155 official program overviews and their available faculty-recommended course maps. Read the courses, elective menus and milestones here.</p><p>UW Seattle, UW Bothell and Bellevue are our priority colleges. An associate transfer degree, an applied degree and a certificate have different requirements and transfer outcomes.</p><label>Search Bellevue programs<input id="bellevue-program-search" type="search" placeholder="Associate, engineering, application development…" maxlength="150"></label><div id="bellevue-programs" class="degree-goals" aria-live="polite"><p role="status">Opening Bellevue’s public program sources…</p></div><section id="bellevue-program-reader" class="degree-optimizer" hidden></section><p class="plan-trust-alert">The official catalog rejected automated access. These accessible public overviews and linked course maps are preserved instead. Course maps are recommendations from the source’s 2025 public snapshot; their example terms are not verified current offerings or approved degree audits.</p>`,'degrees')}
async function renderBellevueSource(id,target,title=''){target.hidden=false;target.innerHTML='<p role="status">Opening the Bellevue program and linked maps…</p>';try{const data=await getBellevueCatalog();if(!target.isConnected)return;const r=data.records.find(r=>r.id===id)||data.records.find(r=>r.title===title);if(!r)throw Error('No exact public source record found for this program.');target.innerHTML=`<span class="eyebrow">BELLEVUE COLLEGE · Checked ${esc(r.checked)}</span><h2>${esc(r.title)}</h2><a class="journey-secondary" href="${esc(r.url)}" target="_blank" rel="noopener">Official program overview ↗</a><div class="uw-source-text" tabindex="0">${esc(r.text)}</div>${r.programs.map(p=>`<article class="degree-goal"><h3>${esc(p.title)} · ${esc(p.award)}</h3><p>${esc(p.description)}</p>${p.additionalRequirements?`<details><summary>Additional source requirements</summary><p>${esc(p.additionalRequirements)}</p></details>`:''}<a class="journey-secondary" href="${esc(p.source)}" target="_blank" rel="noopener">Official recommended map ↗</a><div class="journey-actions">${p.maps.map(m=>`<button class="btn" data-bellevue-map="${esc(m.id)}">Read map: ${esc(m.label)} →</button>`).join('')}</div></article>`).join('')||'<p>No usable linked course map was returned for this overview. The full overview remains above; use the program adviser for the catalog requirements.</p>'}<div data-bellevue-map-reader aria-live="polite"></div><a class="btn" href="#degrees">Add or edit your degree checklist →</a>`;target.querySelectorAll('[data-bellevue-map]').forEach(b=>b.onclick=()=>showBellevueMap(b.dataset.bellevueMap,target.querySelector('[data-bellevue-map-reader]')))}catch(e){if(target.isConnected)target.innerHTML=`<p role="alert">${esc(e.message)}</p>`}}
async function showBellevueMap(id,target){if(!/^[a-f\d-]{36}$/.test(id))return;target.innerHTML='<p role="status">Opening course choices and source milestones…</p>';try{const response=await fetch('bellevue-maps/'+id+'.json');if(!response.ok)throw Error('This course map is unavailable.');const data=await response.json();if(!target.isConnected)return;const terms=new Map();for(const item of data.pathwayElements){const o=item.recommendedOpportunity||{},term=o.term||{},key=[term.year,term.termNumber,term.customLabel].filter(x=>x!==undefined).join(' · ')||'Source term not specified';if(!terms.has(key))terms.set(key,[]);terms.get(key).push(item)}const credits=o=>!Number.isFinite(o.minUnits)||!Number.isFinite(o.maxUnits)||o.minUnits<0||o.maxUnits<0?'Not specified':o.minUnits===o.maxUnits?String(o.minUnits):o.minUnits+'–'+o.maxUnits;target.innerHTML=`<h3>${esc(data.programId)} · ${esc(data.label)}</h3><p>Source term labels are retained below. Verify current prerequisites, course availability, placement, credit totals and your applicable catalog year before registration.</p>${data.missingPrerequisites?.length?`<details class="plan-trust-alert" open><summary>Additional prerequisites identified by the source map</summary>${data.missingPrerequisites.map(c=>`<p>${esc(c.courseCode)} · ${esc(c.title)}</p>`).join('')}</details>`:''}${[...terms].map(([term,items])=>`<section class="degree-goal"><span class="eyebrow">SOURCE MAP TERM · ${esc(term)}</span>${items.map(item=>{const o=item.recommendedOpportunity||{},choice=data.choiceDetails?.[o.masterRecordId];return `<article class="bellevue-map-entry"><h4>${esc(item.name||o.courseCode||o.title||'Source condition')}</h4><p>${esc(item.shortDescription||o.courseName||o.shortDescription||'')}</p>${o.type==='COURSE'?`<p>${esc(credits(o))} source-listed credits · ${esc(item.requirement?.requirementType||'Review applicability')}</p>`:''}${o.type==='MILESTONE'?`<p class="plan-trust-alert">Checkpoint: ${esc(o.longDescription||o.shortDescription||item.name)}</p>`:''}${o.courseNotes?`<p>${esc(o.courseNotes)}</p>`:''}${choice?`<details><summary>Published choice menu · ${esc(choice.name)}</summary><p>${esc(choice.description)}</p>${(choice.opportunityChoices||[]).map(c=>`<p><strong>${esc(c.courseCode||c.title||c.name||c.type)}</strong> · ${esc(c.courseName||c.description||'')} ${c.minUnits!=null?'· '+esc(credits(c))+' credits':''}</p>`).join('')}</details>`:''}</article>`}).join('')}</section>`).join('')}<p class="quiet-note">Relationship edges and source requirement categories are retained in the source snapshot. They have not been certified as a complete prerequisite or degree-sharing rule set.</p>`}catch(e){if(target.isConnected)target.innerHTML=`<p role="alert">${esc(e.message)}</p>`}}
async function bindBellevueCatalog(){const input=document.querySelector('#bellevue-program-search');if(input)try{const data=await getBellevueCatalog();if(!input.isConnected)return;let page=0;const draw=()=>{const rows=data.records.filter(r=>r.title.toLowerCase().includes(input.value.toLowerCase())),target=document.querySelector('#bellevue-programs');target.innerHTML=`<p>${rows.length} matching published overviews · ${data.snapshotYear} linked map snapshot</p>${rows.slice(page*18,(page+1)*18).map(r=>`<article class="degree-goal"><span class="eyebrow">${esc(r.kind)}</span><h3>${esc(r.title)}</h3><button class="btn" data-bellevue-source="${esc(r.id)}">Read overview & course maps →</button></article>`).join('')}<div class="journey-actions"><button class="btn" data-bc-prev ${!page?'disabled':''}>← Previous</button><button class="btn" data-bc-next ${(page+1)*18>=rows.length?'disabled':''}>Next →</button></div>`;target.querySelectorAll('[data-bellevue-source]').forEach(b=>b.onclick=()=>{const reader=document.querySelector('#bellevue-program-reader');renderBellevueSource(b.dataset.bellevueSource,reader).then(()=>reader.scrollIntoView({block:'start',behavior:state.reduceMotion?'auto':'smooth'}))});target.querySelector('[data-bc-prev]').onclick=()=>{page--;draw()};target.querySelector('[data-bc-next]').onclick=()=>{page++;draw()}};input.oninput=()=>{page=0;draw()};draw()}catch(e){if(input.isConnected)document.querySelector('#bellevue-programs').textContent=e.message}document.querySelectorAll('[data-priority-school]').forEach(b=>b.onclick=()=>{programDirectorySchool=b.dataset.prioritySchool;programDirectoryQuery='';programDirectoryPage=0;location.hash='programs';render()})}
function priorityCollegeLinks(){return `<section class="priority-college-links"><span class="eyebrow">PRIORITY COLLEGES</span><div class="journey-actions"><button class="btn" data-priority-school="UW Seattle">UW Seattle →</button><button class="btn" data-priority-school="UW Bothell">UW Bothell →</button><a class="btn" href="#bellevue-catalog">Bellevue College →</a></div></section>`}
async function bindAdmissionSourceNotes(){const target=document.querySelector('[data-admission-source-notes]');if(!target)return;try{const r=await fetch('admission-source-notes.json');if(!r.ok)return;const rows=await r.json();if(!target.isConnected)return;target.innerHTML=`<h3>Published admission GPA context</h3><p>These statements describe groups of admitted students. They are not minimum grades, average GPAs or individual acceptance probabilities.</p>${rows.map(r=>`<article class="degree-goal"><h4>${esc(r.program)} · ${esc(r.population)}</h4><p>${esc(r.publishedText)}</p><p class="quiet-note">${esc(r.cohort)}. ${esc(r.warning)}</p><a class="journey-secondary" href="${esc(r.source)}" target="_blank" rel="noopener">Official source ↗</a></article>`).join('')}`}catch{}}
function installPrioritySources(){const oldExplore=explore;explore=()=>oldExplore()+priorityCollegeLinks();const oldPrograms=programDirectory;programDirectory=(...args)=>oldPrograms(...args)+priorityCollegeLinks();const oldAdvising=advisingPage;advisingPage=()=>oldAdvising()+'<section class="degree-optimizer" data-admission-source-notes></section>';const oldBind=bind;bind=()=>{oldBind();bindBellevueCatalog();bindAdmissionSourceNotes()}}
